INSERT INTO `buku` VALUES (1,' an Introduction to Database Systems: Seventh','C.J. Date','Pearson Educations',2000,NULL,500,'English','','This book is a comprehensive introduction to the now very large field of database systems. It provides a solid grounding in the foundation of database technology and gives some idea of how the fields is likely to develop in the future, The book is meant primarily as a textbook, not a work of reference; the emphasis throughout is on insight and understanding, not just on formalisme.',1,NULL,21,NULL,'2025-03-17 11:00:09','2025-03-24 06:54:10'),(2,' Implementing a database design   using Micro','NIIT','NIIT',2000,NULL,500,'English','','The topic in this book:\n1. Designing a logical database\n2. Normaliing and denormaliing data\n3. Querying and reporting\n4. Creating database\n5. Creating tables and enforcing data ',1,NULL,9,NULL,'2025-03-17 11:00:09','2025-03-19 13:21:48'),(3,' Manultrition, learning, and behaviour?.','Nevin S. Scrimshow','The MIT Press',2000,NULL,500,'English','','The contents this book is:\n1. Philosophical and pragmatic objectives of the conference\n2. Malnutrition and retarded growth in man\n3. Biological factors in central nervous system\n4. Effects of malnutrition on learning and behavior in experimental animals\n5. Malnutrition, learning, and behavior in children\n6. Factor of the social environment affecting learning and behavior\n7. Ecology of malnutrion, learning, and behavior\n8. The field study of malnutrition, learning, and behavior.',1,NULL,4,NULL,'2025-03-17 11:00:09','2025-03-20 13:21:26'),(4,' Samurai from outer space: understanding Japa','Antonia Levi','Open Court',2000,NULL,500,'English','','The contents of this book include:\n1. The birth of the American Otaku\n2. Disney in a kimono\n3. Other Gods, Other demons\n4. Other heroes, other willains\n5. Androids, cyborgs, and other mecha\n6. Etc',1,NULL,2,NULL,'2025-03-17 11:00:09','2025-03-20 13:21:23'),(5,' Swift 2000: Microsoft Outlook : Skill Base','NIIT','NIIT',2000,NULL,500,'English','-','',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-20 13:21:18'),(6,' The economics of the Dolar cycle','Stefan Gerlach & Peter A.Petri','The MIT Press',2000,NULL,500,'English','','The conference was made possible by financial support from the Mellon Foundation and was held with the cooperation of the Research Institute of the Japanese Ministry of International Trade and Industry (MITI/RI) and the Japan Foundation.',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-20 13:21:24'),(7,'?SCJD Exam with J2SE 5, Second Edition','Adrew Monkhouse','Apress',2000,NULL,500,'Inggris','2 ed','The Sun Certified Java Developer (SCJD) examination provides an unparalled oppurtunity to learn new features of J2SE 5. This book will help you master these features and pass the exam by working through a project with requirements and structure similar to that required to earn your SCJD certification.',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-18 08:23:02'),(8,'( Capturing customer ) menangkap pelanggan.Co','George Colombo','PT. Elex Media Komputindo',2000,NULL,500,'Indonesia','','Buku ini tidak membahas tentang teknologi, namun tentang bagaimana kita bisa melakukan pemasaran dan penjualan yang lebih baik dengan mengintegrasikan teknologi–terutama internet–ke dalam model bisnis yang sekarang anda pakai.\nBuku ini menyajikan ide-ide cemerlang dan mematahkan mitos-mitos yang muncul sejak maraknya dotcom sampai kehancurannya akhir-akhir ini.',1,NULL,2,NULL,'2025-03-17 11:00:09','2025-03-19 13:15:44'),(9,'.Net enterprise development in VB.NET : from ','Matthew Reynolds','Wrox Press  & Shroff Publ.',2000,NULL,500,'English','','This book is for people who;\n1. Need to develop secure, scalable, high performance enterprise solutions.\n2. Understand VB.NET and the .NET framework.\n3. Use Visual Studio.NET.',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(10,'Net web services : architecture and implemen','Keith Ballinger','Pearson Educations',2000,NULL,500,'English','-','This book: opens with an introduction to web services and web services standards. it then explores. NET technologies and examines how the NET Framework gives developers the tools they need to build web service applications.',1,NULL,2,NULL,'2025-03-17 11:00:09','2025-03-22 03:44:53'),(11,'[ La memoire d\'Abraham ] The Book of Abraham','Marek Halter','Henry Holt',2000,NULL,500,'English','','',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(12,'1001 plus soal dan pembahasan Fisika: Seleksi','Bob Foster','Erlangga',2000,NULL,500,'Indonesia','6','Topik yang dibahas dalam buku ini adalah:\n1. Besaran dan satuan.\n2. Kinematika gerak lurus.\n3. Dinamika gerak lurus.\n4. Memadu gerak.\n5. Gerak melingkar.\n6. Gravitasi.\n7. Usaha dan energi.\n8. Gesekan.\n9. Momentum dan impuls.\n10. Getaran.\n11. Gelombang.',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-19 06:44:57'),(13,'1001(one thousand And one) ways to market you','John Kremer','Open Horizons',2000,NULL,500,'English','','',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-18 13:26:15'),(14,'101 cara memotivasi diri','Christine Ingham','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Dalam buku ini dimuat 101 cara memotivasi diri, perubahan fisik di lingkungan kantor (rak, kerai, gambr-gambar, bunga dan lain-lain) menurut penulis dapat meningkatkan motivasi diri.\nBeberapa ide yang menurut penulis dapat meningkatkan motivasi diri adalah sebagai berikut:\n1.	Membangun dan memelihara motivasi diri\n2.	Menyingkirkan penghalang fisik dan psikologis untuk bekerja\n3.	Memberi diri sendiri insentif-insentif yang berarti\n4.	Menemukan dukungan positif, aktif mendukung waktu anda membutuhkannya\n5.	Mengembangkan strategi-strategi sederhana dan efektif untuk membantu mengatasi rintangan-rintangan yang sulit terhadap motivasi.\n\n',1,NULL,5,NULL,'2025-03-17 11:00:09','2025-03-26 08:56:06'),(15,'101 cara meningkatkan kepuasan pelanggan','Timothy R.V. roester','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Buku ini menyajikan 101 cara untuk membangundan mempertahankan kepuasan pelanggan. Buku ini memfokuskan pada praktis bisnis internal maupun eksternal yang memepengaruhi hubungan anda dengan pelanggan.',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-19 03:04:45'),(16,'101 helpful hints for IELTS : general trainin','Garry Adams and Terry Peck','Adams & Austen Press',2000,NULL,500,'English','','The book features is :\n1.2 practice listening \n2.4 grade practice general training reading teststice gr \n3.4 practice general taraining writing tests\n',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(17,'101 tip & trik Autocad 2000i','Handi Chandra','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Pembahasan dalam buku ini mencakup: - Menggunakan properties - Membuat dua objek elips berbeda - Menggunting objek blok/xref - Menggunakan titik referensi sementara - Mengatur posisi tumpukan objek - Menggunakan pemilihan grips ganda - Menggunakan grid dan snap bersamaan - Mengisi properti gambar yang aktif - etransit ',1,NULL,6,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(18,'15th international exhibition of drawings 28 ','','Modern Gallery Rijeka, Museum and Contemporar',2000,NULL,500,'English','','\n',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(19,'17 kualitas seorang pemain tim sejati','John c. Maxwell','interaksara',2000,NULL,500,'Indonesia','','Dalam buku ini pengarang menjelaskan:\n1. Bertekad: memastika setiap tindakannya berkontribusi terhadap sasaran jangka panjang\n2. Pandai membina hubungan: terfokus pada orang lain\n3. Tidak mementingkan diri sendiri: bersedia mengalah demi kepentingan tim\n4. Ulet: Suka bekerja keras dan optimis menghadapi kemunduran',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(20,'1993 (nineteen hundreds and nninety three) IE','General Chair & Wai- Kai Chen','IEEE Service Center',2000,NULL,500,'English','','There are several topics included in this book, such as: Video Coding, Adaptive Signal Processing, FIR Filter Design, Filter Banks and Wavelets: Interrelations and Application, Poster: Signal Processing, Images Coding.',1,NULL,6,NULL,'2025-03-17 11:00:09','2025-03-18 13:56:39'),(21,'1999 guide to literary agents: 500 + agents w','edited by Donya Dickerson','Writer\'s digest books',2000,NULL,500,'English','','The contents of this book are:\n1. Leterary agents\n2. Literary agents: nonfee-charging\n3. Literary agents: Fee-charging\n4. script agents\n5. Script agents: Nonfee-charging & fee-charging\n',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(22,'2000 (two thousand)solved problems in discret','Seymour Lipschutz','McGraw-Hill',2000,NULL,500,'English','','The topics in this book are :\nÃ¢â‚¬Â¢	Learn the best strategies for solving tough problems in step-by-step detail\nÃ¢â‚¬Â¢	Prepare effectively for exams and save time in doing homework problems\nÃ¢â‚¬Â¢	Choose from the largest selection of solved problems yet published on this subject\nÃ¢â‚¬Â¢	Use the index to quickly locate the types of problems you most need help with\nÃ¢â‚¬Â¢	Save this book for reference in other course and for your professional libraby\n',1,NULL,9,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(23,'2000 Solved problems in discrete mathematics','Lipschutz, Seymour','McGraw-Hill',2000,NULL,500,'English','','The contens book is:\n1.SEt theory\n2.relations\n3.functions\n4.vectors and matric \n5.graph theory ',1,NULL,5,NULL,'2025-03-17 11:00:09','2025-03-20 13:21:27'),(24,'25 etika profesi','As\'ad Sungguh','Sinar Grafika',2000,NULL,500,'Indonesia','-','Buku ini berisi pasal-pasal hukum yang memberikan batas-batas etika terhadap profesi arsitek, akuntan, notaris, advokat, hakim, koperasi DPR, serta pertanian dan perburuhan.',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(25,'3 rd serving of Chicken Soup for the Soul : 7','Jack Canfield dkk','Gramedia Pustaka Utama',2000,NULL,500,'Indonesia','','Buku Cerita Chicken Soup for the Soul ini menyuguhkan kumpulan cerita kebijaksanaan seputar cinta, mengasuh anak, belajar dan mengajar, kematian, sikap, dan mengatasi hambatan. Buku in akan menghangatkan hati Anda, membuat hari-hari tergelap Anda menjadi cerah kembali, dan memberikan keceriaan pada Anda sepanjang hidup.',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(26,'3 tier client/server at work revised edition','Jeri Edwards','John Wiley & Sons',2000,NULL,500,'English','','02.00393 ? 3 tier client/server at work revised edition\nHal -hal yang di bahas dalam buku ini mencakup  :\nWhy 3-tier architectures are key to successfil enterprise client/server application\nHow to succed with challenging project requirements\nWhat are the architectural trade -oofs and hao to choose between them\nhow Successful projects are run\nwhat outcomes to expect\nword to the wise : tips from the architects',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(27,'Empower your human resources: Berdayakan sumber daya manusia anda','Atmosoeprapto, Kisdarto','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Buku ini menyajikan trik bagaimana memberdayakan sumberdaya manusia yang dimiliki sehingga menghasilkan pekerjaan yang baik. Beberapa topic yang dibahas adalah:\n1.	Sikap\n2.	Pengembangan pikiran\n3.	Pengembangan SDM\n4.	Kepemimpinan.\n\nBuku ini dapat dijadikan pedoman untuk mengasah sifat kepemimpinan.\n',1,NULL,3,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(28,'30 (tigapuluh) menit cara efektif belajar di ','Timur Maharadika','Pondok Edukasi',2000,NULL,500,'Indonesia','','Buku ini menjelaskan bagaimana sebaiknya cara belajar di Perguruan Tinggi,\nsehingga dapat memperoleh pengetahuan baru yang mendalam.\nDengan pengetahuan yang baru itulah,\nkita melahirkan karya-karya dengan makna bagi masa depan bangsa. ',1,NULL,9,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(29,'30 Minutes? To Plan a Project Merencanakan Pr','Trevor Young','Elex Media Komputindo',2000,NULL,500,'Indonesia','','',1,NULL,6,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(30,'36 jam belajar Delphi 5.0','Inge Martina','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Hal-hal yang di bahas dalam buku ini adalah:\n1. Mengenal Delphi dan IDE\n2. Object Pascal\n3. File dan Project Manager\n4. Visual Component Library\n5. File Input/Output\n6. Database dan komponen table\n7. SQL dan query\n8. Event Driven dan Exception',1,NULL,6,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(31,'36 Jam belajar komputer : Database Client/Ser','Inge Martina','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Delphi mendukung pemrograman client/server, tetapi tidak setiap aplikasi Delphi bersifat client/server misalnya Oracle, Microsoft SQL, atau Interbase, tetapi tidak setiap aplikasi yang memakai database tersebut adalah aplikasi client/server. Modul yang dibahas dalam buku ini antara lain mengenai: 1.	Mengenal Delphi dan object Pascal 2. Konsep manajemen database 3.	Database desktop dan konstrain database 4.	Aplikasi database 5.	Memakai komponen table 6.	Data module dan data dictionary 7.	SQL dan komponen query 8.	Aplikasi multiuser 9.	Memakai ODBC dan ADO 10.	Feature ADO 11. Pemrograman client/server 12.	Interbase express 13.	Memakai stored procedure, trigger, dan generator dalam aplikasi ',1,NULL,9,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(32,'36 jam belajar komputer : Microaoft Windows X','Kurweni Ukar','Elex Media Komputindo',2000,NULL,500,'Indonesia','-','Tujuan buku ini disusun adalah agar pembaca dapat mempelajari, memahami dan mencoba penggunaan sistem operasi Microsoft Windows XP Home Edition dan Microsoft Plus secara cepat dan mudah sesuai dengan kebutuhan. Beberapa hal yang dibahas dalam buku ini adalah:\no	Mengenal Microsoft Windows XP Home Edition\no	Mulai bekerja dengan Windows XP\no	Mengatur Taskbar dengan area kerja (desktop) Windows Xp\no	Menjelajahi Komputer, menggunakan Faslitas Help dan Fasilitas Tour Windows XP\no	Mengelola File, Folder, dan Recycle Bin\no	Menggunakan fasilitas Search\no	Menggunakan Fasilitas favorites, Links, History, dan Media\no	Mengatur Penggunaan Perangkat Keras (hardware)\no	Menggunakan dan mengatur Printer\no	Mengatur Konfigurasi Umum Windows XP\no	Menggunakan dan Mengatur Suara dan Perangkat Multimedia lainnya\no	Mengamankan dan Mengoptimalkan Penggunaan Komputer\no	Menggunakan Program Aplikasi Pelengkap (Accessories)\no	Menggunakan Windows Media Player dan Windows Movie Maker\no	Menggunakan fasilitas Komunikasi\no	Mengatur pemakai Komputer (User Accounts) dan menggunakan Windows Task Manager\no	Menggunakan Internet Ekxplorer, mengelola E-mail dengan Outlook Express dan Address Book\no	Menggunakan Microsoft Plus.\n',1,NULL,6,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(33,'36 Jam Belajar Komputer :Delphi 5.0','Inge Martina','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Pembahasan materi dalam buku ini adalah: - Mengenal Delphi dan IDE - Object Pascal - File dan Project Manager - Visual Component Library - File Input/Output - Database dan komponen tabel - SQL dan Query - Event driven dan expection - Dynamic Link Library - Grafik dan multimedia - Multitasking dan thread - Membuat komponen - Membuat laporan - Mencetak',1,NULL,6,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(34,'36 Jam Belajar Komputer Database Client /Serv','Inge Martina','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Modul yang dibahas dalam buku ini antara lain mengenai : 1. Mengenal Delphi dan Object Pascal 2. Konsep manajemen database 3. Database desktop dan konstrain database 4. Aplikasi database 5. Memakai komponen table 6. Data module dan data dictionary 7. SQL dan komponen query 8. Aplikasi multiuser',1,NULL,6,NULL,'2025-03-17 11:00:09','2025-03-17 11:00:09'),(35,'36 Jam belajar komputer Database Client/Serve','Inge Martina','Elex Media Komputindo',2000,NULL,500,'Indonesia','','Modul yang dibahas dalam buku ini antara lain mengenai :\n1. Mengenal Delphi dan Object Pascal\n2. Konsep manajemen database\n3. Database de