INSERT INTO `pengumuman` VALUES (6,'Perubahan Jam Operasional Perpustakaan','Mulai tanggal 1 November 2025, jam operasional perpustakaan akan mengalami perubahan. Perpustakaan akan buka dari pukul 08.00 hingga 17.00 WIB setiap hari Senin hingga Jumat. Untuk hari Sabtu, perpustakaan akan buka dari pukul 09.00 hingga 15.00 WIB, sedangkan hari Minggu tetap tutup. Perubahan ini dilakukan untuk memberikan waktu yang lebih fleksibel bagi staf perpustakaan dalam melakukan pemeliharaan koleksi dan pelayanan. Kami mohon maaf atas ketidaknyamanan ini dan berharap untuk terus melayani Anda dengan lebih baik.','[]','Jadwal Perpustakaan','2025-03-18 01:51:04','2025-03-18 01:51:04'),(7,'Peminjaman Buku Lebih Mudah dengan Aplikasi Mobile','Kini, proses peminjaman buku di perpustakaan semakin mudah dengan adanya fitur peminjaman melalui aplikasi mobile. Anda dapat memilih buku yang tersedia di katalog digital, mengajukan peminjaman, dan menunggu konfirmasi dari staf perpustakaan. Setelah peminjaman disetujui, buku yang dipinjam akan disiapkan dan dapat diambil di meja layanan perpustakaan. Pastikan untuk membawa kartu anggota perpustakaan saat mengambil buku. Untuk informasi lebih lanjut, silakan hubungi layanan pelanggan kami di nomor 0812-3456-7890','[]','Peminjaman Buku','2025-03-18 01:51:43','2025-03-18 01:51:43'),(8,'Workshop Menulis Kreatif di Perpustakaan','Perpustakaan akan mengadakan workshop menulis kreatif pada tanggal 15 November 2023, pukul 10.00 hingga 12.00 WIB. Acara ini terbuka untuk umum dan gratis. Peserta akan diajarkan teknik menulis cerpen, puisi, dan esai oleh penulis ternama, Bapak Ahmad Fauzi. Daftarkan diri Anda melalui aplikasi mobile atau langsung di meja layanan perpustakaan. Tempat terbatas, hanya untuk 50 peserta pertama. Jangan lewatkan kesempatan ini untuk mengasah keterampilan menulis Anda!','[]','Acara Perpustakaan','2025-03-18 01:52:37','2025-03-18 01:52:37'),(9,'Tambahan Koleksi Buku Terbaru di Perpustakaan','Perpustakaan telah menambahkan lebih dari 100 judul buku terbaru ke dalam koleksi kami. Buku-buku ini mencakup berbagai genre, mulai dari fiksi, non-fiksi, sains, hingga buku anak-anak. Beberapa judul yang patut diperhatikan termasuk \"Laut Bercerita\" oleh Leila S. Chudori, \"Sapiens: Riwayat Singkat Umat Manusia\" oleh Yuval Noah Harari, dan \"The Midnight Library\" oleh Matt Haig. Segera kunjungi perpustakaan atau cek katalog digital di aplikasi mobile untuk melihat daftar lengkapnya.','[]','Koleksi Baru','2025-03-18 01:52:57','2025-03-18 01:52:57'),(10,'Perpustakaan Tutup Sementara untuk Perawatan Koleksi','Dalam rangka perawatan dan pemeliharaan koleksi, perpustakaan akan tutup sementara pada tanggal 20-22 November 2023. Selama penutupan, staf perpustakaan akan melakukan pengecekan kondisi buku, perbaikan kerusakan, dan pembersihan rak-rak buku. Kami memohon maaf atas ketidaknyamanan ini dan berharap untuk kembali melayani Anda dengan koleksi yang lebih terawat. Untuk informasi lebih lanjut, silakan hubungi kami di nomor 0812-3456-7890','[]','Perawatan Koleksi','2025-03-18 01:53:19','2025-03-18 01:53:19'),(11,'Perpustakaan Digital Resmi Diluncurkan','Perpustakaan digital kami resmi diluncurkan! Kini, Anda dapat mengakses ribuan e-book, jurnal, dan artikel ilmiah secara online melalui aplikasi mobile. Cukup login menggunakan akun anggota perpustakaan Anda dan nikmati kemudahan membaca di mana saja dan kapan saja. Untuk informasi lebih lanjut, kunjungi situs web kami di www.perpustakaan-digital.com atau hubungi layanan pelanggan di nomor 0812-3456-7890.','[]','Teknologi Perpustakaan','2025-03-18 01:53:54','2025-03-18 01:53:54'),(12,'Sosialisasi Cara Menggunakan Aplikasi Perpustakaan Mobile','Bagi anggota perpustakaan yang belum familiar dengan aplikasi mobile kami, kami akan mengadakan sosialisasi pada tanggal 25 November 2023, pukul 14.00 hingga 16.00 WIB. Acara ini akan membahas cara menggunakan fitur-fitur aplikasi, seperti peminjaman buku, pengembalian buku, dan akses ke perpustakaan digital. Acara gratis dan terbuka untuk umum. Daftarkan diri Anda melalui aplikasi atau langsung di meja layanan perpustakaan','[]','Sosialisasi','2025-03-18 01:54:19','2025-03-18 01:54:19'),(13,'Perpustakaan Tutup Sementara untuk Renovasi','Dalam rangka renovasi dan perluasan ruang baca, perpustakaan akan tutup sementara mulai tanggal 1 Desember 2023 hingga 15 Desember 2023. Selama penutupan, layanan peminjaman dan pengembalian buku akan dialihkan ke perpustakaan cabang di Jl. Merdeka No. 10. Kami memohon maaf atas ketidaknyamanan ini dan berharap untuk kembali melayani Anda dengan fasilitas yang lebih baik. Untuk informasi lebih lanjut, silakan hubungi kami di nomor 0812-3456-7890','[]','Penutupan Sementara','2025-03-18 01:54:36','2025-03-18 01:54:36'),(21,'Pengembalian Buku Tanpa Antri dengan Drop Box','Untuk memudahkan proses pengembalian buku, perpustakaan kini menyediakan drop box yang dapat digunakan di luar jam operasional. Drop box ini terletak di depan pintu masuk perpustakaan dan dapat diakses 24 jam. Pastikan buku yang dikembalikan dalam kondisi baik dan tidak rusak. Setelah buku dikembalikan, staf perpustakaan akan memproses pengembalian dan mengirimkan notifikasi melalui aplikasi mobile. Jika ada masalah atau pertanyaan, silakan hubungi kami melalui email di perpustakaan@example.com.','[]','Pengembalian Buku','2025-03-18 03:59:35','2025-03-18 03:59:35'),(22,'Promo Gratis Biaya Admin untuk Pendaftaran Anggota Baru','Dalam rangka memperingati Hari Buku Nasional, perpustakaan memberikan promo gratis biaya admin untuk pendaftaran anggota baru selama bulan November 2023. Syarat dan ketentuan berlaku:\r\n\r\nMembawa fotokopi KTP atau kartu pelajar.\r\n\r\nMengisi formulir pendaftaran di meja layanan perpustakaan.\r\n\r\nPromo ini hanya berlaku untuk 100 pendaftar pertama.\r\nSegera daftarkan diri Anda dan nikmati akses ke ribuan koleksi buku kami!','[]','Promo Perpustakaan','2025-03-18 04:00:40','2025-03-18 04:00:40'),(40,'Kuisioner','Kuisioner ta https://forms.gle/iCoRxG8NNiRuqRJP6','[]','Kuisioner','2025-03-20 12:50:26','2025-03-20 12:50:26');
/*!40000 ALTER TABLE `pengumuman` ENABLE KEYS */;
UNLOCK TABLES;

